#include "dmod.h"
#include "dmosi.h"
#include "libdmview.h"
#include "calc.h"
#include <errno.h>
#include <string.h>

/**
 * @brief calculator - a pocket calculator that lives in a rent of the screen.
 *
 * Usage: calculator [--display NAME] [<view>]
 *
 * NAME is the display it takes, or the rent of one that its owner gave it (the launcher of phoneui passes it to every application it
 * starts); without it, the first display. The view (views/calculator.dmvs, generated by scripts/gen_view.py) draws the display and the
 * keys into what it is given; the application sets its two properties - "expr" (the small line) and "text" (the number) - and is told of
 * a key by the event "press" (the value is the key's code, see calc.h). The keyboard works too: digits, the operations, Enter (=),
 * Backspace and C. The application ends when its claim is gone - the owner took the rent back.
 */

#define DEFAULT_VIEW    "/eviews/calculator/calculator.dmv"     /* dmod-boot: views of the flash modules */
#define WAIT_MS         100u
#define DISPLAY_WAIT_MS 10000u
#define KEY_ENTER       0x28
#define KEY_BACKSPACE   0x2A

/* The key of the calculator that a character of the keyboard is, 0: none */
static char key_of_char(uint32_t c)
{
    switch (c)
    {
        case ',': return '.';
        case 'x': case 'X': return '*';
        case 'C': return 'c';
        case '\n': case '\r': return '=';
        default: break;
    }
    return (c < 0x7F && strchr("0123456789.+-*/=%cn", (int)c) != NULL && c != 0) ? (char)c : 0;
}

/* What the view shows is set when it changes: on an e-paper every change is a refresh */
static void show(uint32_t claim, const calc_t* calc, calc_t* shown)
{
    if (strcmp(calc->text, shown->text) != 0)
        (void)libdmview_prop_set_string(claim, "text", calc->text);
    if (strcmp(calc->expr, shown->expr) != 0)
        (void)libdmview_prop_set_string(claim, "expr", calc->expr);
    *shown = *calc;
}

static int claim_display(const char* display, const char* view, uint32_t* claim)
{
    dmosi_semaphore_t wakeup = dmosi_semaphore_create(0, 1);
    if (wakeup == NULL)
        return -ENOMEM;
    int ret = -ENODEV;
    for (uint32_t waited = 0; waited <= DISPLAY_WAIT_MS; waited += WAIT_MS)
    {
        ret = libdmview_claim(display, view, claim);       /* (the rent or the display may be there a moment after this starts) */
        if (ret != -ENODEV)
            break;
        (void)dmosi_semaphore_wait(wakeup, 1, (int32_t)WAIT_MS);
    }
    dmosi_semaphore_destroy(wakeup);
    return ret;
}

int main(int argc, char* argv[])
{
    const char* display = NULL;
    const char* view = DEFAULT_VIEW;
    for (int i = 1; i < argc; i++)
    {
        if (strcmp(argv[i], "--display") == 0 && i + 1 < argc)
            display = argv[++i];
        else if (argv[i][0] != '\0')
            view = argv[i];
    }

    uint32_t claim = 0;
    int ret = claim_display(display, view, &claim);
    if (ret != 0)
    {
        DMOD_LOG_ERROR("calculator: cannot claim %s (%d)\n", (display != NULL) ? display : "a display", ret);
        return ret;
    }

    calc_t calc, shown;
    calc_reset(&calc);
    memset(&shown, 0, sizeof(shown));
    shown.text[0] = '0';                                    /* (what the view starts with) */
    DMOD_LOG_INFO("calculator: showing %s on %s\n", view, (display != NULL) ? display : "the display");

    libdmview_event_t ev;
    while ((ret = libdmview_wait_event(claim, &ev, -1)) != -ENOENT)
    {
        if (ret != 0)
            continue;
        char key = 0;
        if (strcmp(ev.name, "press") == 0)
            key = (char)ev.value;
        else if (strcmp(ev.name, "char") == 0)
            key = key_of_char((uint32_t)ev.value);
        else if (strcmp(ev.name, "key") == 0 && ev.value == KEY_ENTER)
            key = '=';
        else if (strcmp(ev.name, "key") == 0 && ev.value == KEY_BACKSPACE)
            key = 'b';
        if (key != 0 && calc_key(&calc, key))
            show(claim, &calc, &shown);
    }
    DMOD_LOG_INFO("calculator: its claim is gone - ends\n");
    return 0;
}
